package practice;

public final class LenientParser {

    private LenientParser() {
    }

    /** Returns the int written in {@code text} (whitespace ignored), or {@code fallback} when it is not one. */
    public static int parseOrDefault(String text, int fallback) {
        String trimmed = text.strip();
        try {
            return Integer.parseInt(trimmed);
        } catch (NumberFormatException e) {
            return fallback;
        }
    }
}

